'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import { MoreHorizontal } from 'lucide-react';

export function Header() {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isDark, setIsDark] = useState(false);

  const navigation = [
    { name: 'Demo', href: '/demo' },
    { name: 'Pricing', href: '/pricing' },
    { name: 'About', href: '/about' }
  ];

  useEffect(() => {
    const saved = localStorage.getItem('theme');
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    const theme = saved === 'dark' || (!saved && prefersDark);
    setIsDark(theme);
    document.documentElement.classList.toggle('dark', theme);
  }, []);

  const toggleTheme = () => {
    const newTheme = !isDark;
    setIsDark(newTheme);
    localStorage.setItem('theme', newTheme ? 'dark' : 'light');
    document.documentElement.classList.toggle('light', !newTheme);
  };

  return (
    <>
      {/* Floating Navbar - Theme Inverted */}
      <header className="fixed top-4 left-1/2 transform -translate-x-1/2 z-50">
        <nav className="navbar-glass px-6 py-3 flex items-center space-x-6">
          {/* Logo */}
          <Link href="/" className="flex items-center space-x-2">
            <img 
              src="/logo-black.svg" 
              alt="SenScript Logo" 
              className="w-7 h-7 block dark:hidden"
            />
            <img 
              src="/logo-white.svg" 
              alt="SenScript Logo" 
              className="w-7 h-7 hidden dark:block"
            />
            <span className="font-medium hidden sm:block text-white dark:text-gray-900">SenScript</span>
          </Link>

          {/* Desktop Navigation */}
          <div className="hidden md:flex items-center space-x-4">
            {navigation.map((item) => (
              <Link
                key={item.name}
                href={item.href}
                className="text-sm font-medium text-gray-300 dark:text-gray-700 hover:text-orange-500 transition-colors"
              >
                {item.name}
              </Link>
            ))}
          </div>

          {/* Theme Toggle */}
          <button
            onClick={toggleTheme}
            className="p-2 rounded-lg text-gray-300 dark:text-gray-700 hover:bg-white/10 dark:hover:bg-gray-200 transition-colors"
          >
            <span className="material-symbols-outlined icon-sm">
              {isDark ? 'light_mode' : 'dark_mode'}
            </span>
          </button>

          {/* Mobile Menu Button */}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="md:hidden p-2 rounded-lg hover:bg-black/10 dark:hover:bg-white/10 transition-colors"
          >
            <MoreHorizontal className="w-4 h-4" />
          </button>

          {/* CTA Button */}
          <Link href="/demo" className="btn btn-primary text-sm px-4 py-2">
            Try Free
          </Link>
        </nav>
      </header>

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div className="fixed inset-0 z-40 md:hidden">
          <div 
            className="absolute inset-0 bg-black/20 dark:bg-black/40"
            onClick={() => setIsMobileMenuOpen(false)}
          />
          <div className="absolute top-20 left-1/2 transform -translate-x-1/2">
            <div className="glass p-4 space-y-2">
              {navigation.map((item) => (
                <Link
                  key={item.name}
                  href={item.href}
                  className="block px-4 py-2 text-sm font-medium hover:bg-black/10 dark:hover:bg-white/10 rounded-lg transition-colors"
                  onClick={() => setIsMobileMenuOpen(false)}
                >
                  {item.name}
                </Link>
              ))}
            </div>
          </div>
        </div>
      )}
    </>
  );
}

export default Header;